#define MCP_JSON_MAX_DEPTH 32U
#define MCP_JSON_MAX_TOKENS 65536U
#define MCP_JSON_NO_TOKEN SIZE_MAX

typedef enum mcp_json_type {
    MCP_JSON_OBJECT,
    MCP_JSON_ARRAY,
    MCP_JSON_STRING,
    MCP_JSON_NUMBER,
    MCP_JSON_TRUE,
    MCP_JSON_FALSE,
