use crate::JsonDocument;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JsonBufferError {
    Limit,
    Allocation,
    InvalidToken,
    Overflow,
}

/// An owned output buffer whose append operations are atomic on failure.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JsonBuffer {
    bytes: Vec<u8>,
    limit: usize,
}

impl JsonBuffer {
    pub fn new(initial_capacity: usize, limit: usize) -> Result<Self, JsonBufferError> {
        if limit == 0 || initial_capacity > limit { return Err(JsonBufferError::Limit); }
        let mut bytes = Vec::new();
        bytes.try_reserve_exact(initial_capacity).map_err(|_| JsonBufferError::Allocation)?;
        Ok(Self { bytes, limit })
    }

    pub fn as_bytes(&self) -> &[u8] { &self.bytes }
    pub fn len(&self) -> usize { self.bytes.len() }
    pub fn is_empty(&self) -> bool { self.bytes.is_empty() }
    pub fn limit(&self) -> usize { self.limit }

    pub fn append(&mut self, bytes: &[u8]) -> Result<(), JsonBufferError> {
        let needed = self.bytes.len().checked_add(bytes.len()).ok_or(JsonBufferError::Overflow)?;
        if needed > self.limit { return Err(JsonBufferError::Limit); }
        self.bytes.try_reserve(bytes.len()).map_err(|_| JsonBufferError::Allocation)?;
        self.bytes.extend_from_slice(bytes);
        Ok(())
    }

    /// Appends a slice already in this buffer, using checked offsets instead of aliased pointers.
    pub fn append_within(&mut self, range: std::ops::Range<usize>) -> Result<(), JsonBufferError> {
        if range.start > range.end || range.end > self.bytes.len() {
            return Err(JsonBufferError::InvalidToken);
        }
        let count = range.end - range.start;
        let needed = self.bytes.len().checked_add(count).ok_or(JsonBufferError::Overflow)?;
        if needed > self.limit { return Err(JsonBufferError::Limit); }
        self.bytes.try_reserve(count).map_err(|_| JsonBufferError::Allocation)?;
        self.bytes.extend_from_within(range);
        Ok(())
    }

    pub fn literal(&mut self, literal: &str) -> Result<(), JsonBufferError> {
        self.append(literal.as_bytes())
    }

    pub fn quoted(&mut self, data: &[u8]) -> Result<(), JsonBufferError> {
        let escaped = data.iter().try_fold(2_usize, |size, byte| {
            size.checked_add(match byte {
                b'"' | b'\\' | 8 | 12 | b'\n' | b'\r' | b'\t' => 2,
                0..=0x1f => 6,
                _ => 1,
            })
        }).ok_or(JsonBufferError::Overflow)?;
        let needed = self.bytes.len().checked_add(escaped).ok_or(JsonBufferError::Overflow)?;
        if needed > self.limit { return Err(JsonBufferError::Limit); }
        self.bytes.try_reserve(escaped).map_err(|_| JsonBufferError::Allocation)?;
        self.bytes.push(b'"');
        for byte in data {
            match *byte {
                b'"' | b'\\' => { self.bytes.push(b'\\'); self.bytes.push(*byte); }
                8 => self.bytes.extend_from_slice(b"\\b"),
                12 => self.bytes.extend_from_slice(b"\\f"),
                b'\n' => self.bytes.extend_from_slice(b"\\n"),
                b'\r' => self.bytes.extend_from_slice(b"\\r"),
                b'\t' => self.bytes.extend_from_slice(b"\\t"),
                0..=0x1f => {
                    const HEX: &[u8; 16] = b"0123456789abcdef";
                    self.bytes.extend_from_slice(&[b'\\', b'u', b'0', b'0', HEX[(byte >> 4) as usize], HEX[(byte & 0xf) as usize]]);
                }
                _ => self.bytes.push(*byte),
            }
        }
        self.bytes.push(b'"');
        Ok(())
    }

    pub fn raw_token(&mut self, document: &JsonDocument<'_>, token: usize) -> Result<(), JsonBufferError> {
        let raw = document.raw_token(token).ok_or(JsonBufferError::InvalidToken)?;
        self.append(raw)
    }
}

use vexel_json::{JsonBuffer, JsonBufferError, JsonDocument, JsonError, JsonType, MAX_BYTES, MAX_DEPTH, MAX_TOKENS};

#[test]
fn parses_ordered_containers_duplicate_keys_and_raw_spans() {
    let source = br#" {"a":[true,false,null,12],"s":"x\uD83D\uDE00\n","a":0} "#;
    let doc = JsonDocument::parse(source).unwrap();
    assert_eq!(doc.root(), 0);
    assert_eq!(doc.token(doc.root()).unwrap().kind, JsonType::Object);
    assert_eq!(doc.token(doc.root()).unwrap().child_count, 6);
    let first_a = doc.object_get(doc.root(), b"a").unwrap();
    assert_eq!(doc.token(first_a).unwrap().kind, JsonType::Array);
    assert_eq!(doc.array_get(first_a, 0).and_then(|i| doc.bool(i)), Some(true));
    assert_eq!(doc.array_get(first_a, 1).and_then(|i| doc.bool(i)), Some(false));
    assert_eq!(doc.array_get(first_a, 2).and_then(|i| doc.token(i)).unwrap().kind, JsonType::Null);
    assert_eq!(doc.array_get(first_a, 3).and_then(|i| doc.uint(i)), Some(12));
    let string = doc.object_get(doc.root(), b"s").unwrap();
    assert_eq!(doc.decoded_string(string).unwrap(), b"x\xf0\x9f\x98\x80\n");
    assert_eq!(doc.raw_token(doc.root()).unwrap(), br#"{"a":[true,false,null,12],"s":"x\uD83D\uDE00\n","a":0}"#);
    assert_eq!(doc.object_get(doc.root(), b"a"), Some(first_a));
    assert_eq!(doc.array_get(first_a, 99), None);
    let catalog = format!("[{}]", vec!["{}"; 24].join(","));
    let catalog_doc = JsonDocument::parse(catalog.as_bytes()).unwrap();
    assert_eq!(catalog_doc.token(catalog_doc.root()).unwrap().kind, JsonType::Array);
    assert!(catalog_doc.token(catalog_doc.root()).unwrap().child_count >= 20);
}

#[test]
fn strict_malformed_and_utf8_cases_match_reference_parser() {
    for source in [b"".as_slice(), b"{", b"[1,]", br#"{"a" 1}"#, b"01", b"1e", br#""\uD800""#, br#""\uDC00""#, br#""\x""#, b"true false", b"[NaN]"] {
        assert!(JsonDocument::parse(source).is_err(), "accepted {source:?}");
    }
    for source in [&b"\"\xc0\xaf\""[..], &b"\"\xed\xa0\x80\""[..], &b"\"\xf4\x90\x80\x80\""[..]] {
        assert_eq!(JsonDocument::parse(source), Err(JsonError::Invalid));
    }
    assert!(JsonDocument::parse(b"\"nul\\u0000byte\"").unwrap().decoded_string(0).unwrap().contains(&0));
    assert_eq!(JsonDocument::parse(br#""line\n\t\/\\\"\u00e9""#).unwrap().decoded_string(0).unwrap(), "line\n\t/\\\"é".as_bytes());
}

#[test]
fn numbers_obey_json_grammar_and_uint_is_checked_decimal_only() {
    for number in [b"-0".as_slice(), b"0.0", b"1e+2", b"-3E-4"] {
        let doc = JsonDocument::parse(number).unwrap();
        assert_eq!(doc.token(doc.root()).unwrap().kind, JsonType::Number);
        assert_eq!(doc.uint(doc.root()), None);
    }
    let doc = JsonDocument::parse(b"18446744073709551615").unwrap();
    assert_eq!(doc.uint(doc.root()), Some(u64::MAX));
    for number in [b"18446744073709551616".as_slice(), b"-1", b"1.0", b"1e2"] {
        let doc = JsonDocument::parse(number).unwrap();
        assert_eq!(doc.uint(doc.root()), None);
    }
    let doc = JsonDocument::parse(b"[true,false,null,0]").unwrap();
    assert_eq!(doc.bool(doc.array_get(doc.root(), 0).unwrap()), Some(true));
    assert_eq!(doc.bool(doc.array_get(doc.root(), 1).unwrap()), Some(false));
    assert_eq!(doc.bool(doc.array_get(doc.root(), 2).unwrap()), None);
}

#[test]
fn depth_token_and_byte_limits_are_enforced() {
    let accepted = format!("{}0{}", "[".repeat(MAX_DEPTH), "]".repeat(MAX_DEPTH));
    assert!(JsonDocument::parse(accepted.as_bytes()).is_ok());
    let rejected = format!("[{}0{}]", "[".repeat(MAX_DEPTH), "]".repeat(MAX_DEPTH));
    assert_eq!(JsonDocument::parse(rejected.as_bytes()), Err(JsonError::TooDeep));
    let too_many = format!("[{}]", vec!["0"; MAX_TOKENS].join(","));
    assert_eq!(JsonDocument::parse(too_many.as_bytes()), Err(JsonError::TooManyTokens));
    assert_eq!(JsonDocument::parse(&vec![b' '; MAX_BYTES + 1]), Err(JsonError::TooLarge));
    assert_eq!(JsonDocument::parse_owned(b"[1]").unwrap().source(), b"[1]");
}

#[test]
fn buffer_quotes_raw_tokens_and_rolls_back_failed_appends() {
    assert_eq!(JsonBuffer::new(3, 2), Err(JsonBufferError::Limit));
    assert_eq!(JsonBuffer::new(0, 0), Err(JsonBufferError::Limit));
    let mut output = JsonBuffer::new(1, 64).unwrap();
    output.literal("prefix:").unwrap();
    let checkpoint = output.as_bytes().to_vec();
    assert_eq!(output.append(&[0; 100]), Err(JsonBufferError::Limit));
    assert_eq!(output.as_bytes(), checkpoint);
    output.append_within(0..3).unwrap();
    assert!(output.as_bytes().ends_with(b"pre"));
    assert_eq!(output.append_within(0..usize::MAX), Err(JsonBufferError::InvalidToken));
    assert_eq!(output.quoted(b"\"\\\x08\x0c\n\r\t\x00\x1f\xc3\xa9").unwrap(), ());
    assert_eq!(&output.as_bytes()[10..], b"\"\\\"\\\\\\b\\f\\n\\r\\t\\u0000\\u001f\xc3\xa9\"");
    let doc = JsonDocument::parse(br#"{"raw": [1, true]}"#).unwrap();
    let array = doc.object_get(doc.root(), b"raw").unwrap();
    output.raw_token(&doc, array).unwrap();
    assert!(output.as_bytes().ends_with(b"[1, true]"));
    let prior = output.as_bytes().to_vec();
    let mut tiny = JsonBuffer::new(0, 2).unwrap();
    assert_eq!(tiny.quoted(b"x"), Err(JsonBufferError::Limit));
    assert!(tiny.is_empty());
    assert_eq!(output.as_bytes(), prior);
    assert_eq!(output.raw_token(&doc, usize::MAX), Err(JsonBufferError::InvalidToken));
}

#include "mcp_json.h"

#include <stdlib.h>
#include <string.h>

typedef struct json_parser {
    mcp_json_doc *doc;
    size_t cursor;
} json_parser;

static void skip_space(json_parser *parser)
{
    while (parser->cursor < parser->doc->source_length) {
        uint8_t byte = parser->doc->source[parser->cursor];
        if (byte != ' ' && byte != '\t' && byte != '\r' && byte != '\n') break;
        parser->cursor++;
    }
}

static bool hex_digit(uint8_t byte, uint32_t *out)
{
    if (byte >= '0' && byte <= '9') *out = (uint32_t)(byte - '0');
    else if (byte >= 'a' && byte <= 'f') *out = (uint32_t)(byte - 'a') + 10U;
    else if (byte >= 'A' && byte <= 'F') *out = (uint32_t)(byte - 'A') + 10U;
    else return false;
    return true;
}

static bool read_hex4(json_parser *parser, uint32_t *out)
{
    if (parser->doc->source_length - parser->cursor < 4U) return false;
    uint32_t value = 0U;
    for (size_t index = 0U; index < 4U; index++) {
        uint32_t digit = 0U;
        if (!hex_digit(parser->doc->source[parser->cursor++], &digit)) return false;
        value = (value << 4U) | digit;
    }
    *out = value;
    return true;
}

static bool utf8_width(const uint8_t *source, size_t length, size_t offset,
                       size_t *out_width)
{
    uint8_t first = source[offset];
    if (first < 0x80U) { *out_width = 1U; return true; }
    size_t width = first >= 0xc2U && first <= 0xdfU ? 2U :
        first >= 0xe0U && first <= 0xefU ? 3U :
        first >= 0xf0U && first <= 0xf4U ? 4U : 0U;
    if (width == 0U || width > length - offset) return false;
    uint8_t second = source[offset + 1U];
    if ((second & 0xc0U) != 0x80U ||
        (first == 0xe0U && second < 0xa0U) ||
        (first == 0xedU && second >= 0xa0U) ||
        (first == 0xf0U && second < 0x90U) ||
        (first == 0xf4U && second >= 0x90U)) return false;
    for (size_t index = 2U; index < width; index++)
        if ((source[offset + index] & 0xc0U) != 0x80U) return false;
    *out_width = width;
    return true;
}

static size_t add_token(mcp_json_doc *doc, mcp_json_type type, size_t start)
{
    if (doc->token_count >= doc->token_capacity) return MCP_JSON_NO_TOKEN;
    size_t index = doc->token_count++;
    doc->tokens[index] = (mcp_json_token){type, start, start,
        MCP_JSON_NO_TOKEN, MCP_JSON_NO_TOKEN, MCP_JSON_NO_TOKEN, 0U};
    return index;
}

static bool append_child(mcp_json_doc *doc, size_t parent, size_t child)
{
    if (parent >= doc->token_count || child >= doc->token_count) return false;
    mcp_json_token *parent_token = &doc->tokens[parent];
    if (parent_token->first_child == MCP_JSON_NO_TOKEN) {
        parent_token->first_child = child;
    } else {
        doc->tokens[parent_token->last_child].next_sibling = child;
    }
    parent_token->last_child = child;
    parent_token->child_count++;
    return true;
}

static bool parse_string(json_parser *parser, size_t parent, size_t *out_token)
{
    const size_t start = parser->cursor;
    if (parser->doc->source[parser->cursor++] != '"') return false;
    while (parser->cursor < parser->doc->source_length) {
        uint8_t byte = parser->doc->source[parser->cursor];
        if (byte == '"') {
            parser->cursor++;
            size_t token = add_token(parser->doc, MCP_JSON_STRING, start);
            if (token == MCP_JSON_NO_TOKEN) return false;
            parser->doc->tokens[token].end = parser->cursor;
            if (parent != MCP_JSON_NO_TOKEN && !append_child(parser->doc, parent, token)) return false;
            *out_token = token;
            return true;
        }
        if (byte < 0x20U) return false;
        if (byte == '\\') {
            parser->cursor++;
            if (parser->cursor >= parser->doc->source_length) return false;
            uint8_t escape = parser->doc->source[parser->cursor++];
            if (escape == '"' || escape == '\\' || escape == '/' || escape == 'b' ||
                escape == 'f' || escape == 'n' || escape == 'r' || escape == 't') continue;
            if (escape != 'u') return false;
            uint32_t codepoint = 0U;
            if (!read_hex4(parser, &codepoint)) return false;
            if (codepoint >= 0xd800U && codepoint <= 0xdbffU) {
                if (parser->doc->source_length - parser->cursor < 6U ||
                    parser->doc->source[parser->cursor] != '\\' ||
                    parser->doc->source[parser->cursor + 1U] != 'u') return false;
                parser->cursor += 2U;
                uint32_t low = 0U;
                if (!read_hex4(parser, &low) || low < 0xdc00U || low > 0xdfffU) return false;
            } else if (codepoint >= 0xdc00U && codepoint <= 0xdfffU) return false;
            continue;
        }
        if (byte >= 0x80U) {
            size_t width = 0U;
            if (!utf8_width(parser->doc->source, parser->doc->source_length,
                            parser->cursor, &width)) return false;
            parser->cursor += width;
        } else parser->cursor++;
    }
    return false;
}

static bool parse_value(json_parser *parser, size_t parent, size_t depth, size_t *out_token);

static bool parse_container(json_parser *parser, size_t parent, size_t depth,
                            bool object, size_t *out_token)
{
    if (depth >= MCP_JSON_MAX_DEPTH) return false;
    const uint8_t opening = object ? '{' : '[';
    const uint8_t closing = object ? '}' : ']';
    if (parser->doc->source[parser->cursor++] != opening) return false;
    size_t container = add_token(parser->doc,
        object ? MCP_JSON_OBJECT : MCP_JSON_ARRAY, parser->cursor - 1U);
    if (container == MCP_JSON_NO_TOKEN) return false;
    if (parent != MCP_JSON_NO_TOKEN && !append_child(parser->doc, parent, container)) return false;
    skip_space(parser);
    if (parser->cursor < parser->doc->source_length &&
        parser->doc->source[parser->cursor] == closing) {
        parser->doc->tokens[container].end = ++parser->cursor;
        *out_token = container;
        return true;
    }
    for (;;) {
        skip_space(parser);
        if (parser->cursor >= parser->doc->source_length) return false;
        if (object) {
            size_t key = MCP_JSON_NO_TOKEN;
            if (parser->doc->source[parser->cursor] != '"' ||
                !parse_string(parser, container, &key)) return false;
            skip_space(parser);
            if (parser->cursor >= parser->doc->source_length ||
                parser->doc->source[parser->cursor++] != ':') return false;
            skip_space(parser);
        }
        size_t child = MCP_JSON_NO_TOKEN;
        if (!parse_value(parser, container, depth + 1U, &child)) return false;
        skip_space(parser);
        if (parser->cursor >= parser->doc->source_length) return false;
        uint8_t delimiter = parser->doc->source[parser->cursor++];
        if (delimiter == closing) {
            parser->doc->tokens[container].end = parser->cursor;
            *out_token = container;
            return true;
        }
        if (delimiter != ',') return false;
        skip_space(parser);
        if (parser->cursor >= parser->doc->source_length ||
            parser->doc->source[parser->cursor] == closing) return false;
    }
}

static bool parse_number(json_parser *parser, size_t parent, size_t *out_token)
{
    size_t start = parser->cursor;
    if (parser->doc->source[parser->cursor] == '-') parser->cursor++;
    if (parser->cursor >= parser->doc->source_length) return false;
    if (parser->doc->source[parser->cursor] == '0') parser->cursor++;
    else {
        if (parser->doc->source[parser->cursor] < '1' || parser->doc->source[parser->cursor] > '9') return false;
        while (parser->cursor < parser->doc->source_length &&
               parser->doc->source[parser->cursor] >= '0' &&
               parser->doc->source[parser->cursor] <= '9') parser->cursor++;
    }
    if (parser->cursor < parser->doc->source_length && parser->doc->source[parser->cursor] == '.') {
        parser->cursor++;
        size_t first_fraction = parser->cursor;
        while (parser->cursor < parser->doc->source_length &&
               parser->doc->source[parser->cursor] >= '0' &&
               parser->doc->source[parser->cursor] <= '9') parser->cursor++;
        if (parser->cursor == first_fraction) return false;
    }
    if (parser->cursor < parser->doc->source_length &&
        (parser->doc->source[parser->cursor] == 'e' || parser->doc->source[parser->cursor] == 'E')) {
        parser->cursor++;
        if (parser->cursor < parser->doc->source_length &&
            (parser->doc->source[parser->cursor] == '+' || parser->doc->source[parser->cursor] == '-')) parser->cursor++;
        size_t first_exponent = parser->cursor;
        while (parser->cursor < parser->doc->source_length &&
               parser->doc->source[parser->cursor] >= '0' &&
               parser->doc->source[parser->cursor] <= '9') parser->cursor++;
        if (parser->cursor == first_exponent) return false;
    }
    size_t token = add_token(parser->doc, MCP_JSON_NUMBER, start);
    if (token == MCP_JSON_NO_TOKEN) return false;
    parser->doc->tokens[token].end = parser->cursor;
    if (parent != MCP_JSON_NO_TOKEN && !append_child(parser->doc, parent, token)) return false;
    *out_token = token;
    return true;
}

static bool parse_value(json_parser *parser, size_t parent, size_t depth, size_t *out_token)
{
    skip_space(parser);
    if (parser->cursor >= parser->doc->source_length) return false;
    uint8_t byte = parser->doc->source[parser->cursor];
    if (byte == '{') return parse_container(parser, parent, depth, true, out_token);
    if (byte == '[') return parse_container(parser, parent, depth, false, out_token);
    if (byte == '"') return parse_string(parser, parent, out_token);
    if (byte == '-' || (byte >= '0' && byte <= '9')) return parse_number(parser, parent, out_token);
    const char *literal = byte == 't' ? "true" : byte == 'f' ? "false" : byte == 'n' ? "null" : NULL;
    if (literal == NULL) return false;
    size_t length = strlen(literal);
    if (length > parser->doc->source_length - parser->cursor ||
        memcmp(parser->doc->source + parser->cursor, literal, length) != 0) return false;
    mcp_json_type type = byte == 't' ? MCP_JSON_TRUE : byte == 'f' ? MCP_JSON_FALSE : MCP_JSON_NULL;
    size_t start = parser->cursor;
    parser->cursor += length;
    size_t token = add_token(parser->doc, type, start);
    if (token == MCP_JSON_NO_TOKEN) return false;
    parser->doc->tokens[token].end = parser->cursor;
    if (parent != MCP_JSON_NO_TOKEN && !append_child(parser->doc, parent, token)) return false;
    *out_token = token;
    return true;
}

bool mcp_json_parse(const uint8_t *source, size_t length, mcp_json_doc *out)
{
    if (out == NULL || source == NULL || length == 0U || length > MCP_JSON_MAX_BYTES) return false;
    *out = (mcp_json_doc){0};
    size_t capacity = length + 1U;
    if (capacity > MCP_JSON_MAX_TOKENS) capacity = MCP_JSON_MAX_TOKENS;
    out->tokens = calloc(capacity, sizeof(*out->tokens));
    if (out->tokens == NULL) return false;
    out->source = source;
    out->source_length = length;
    out->token_capacity = capacity;
    json_parser parser = {out, 0U};
    size_t root = MCP_JSON_NO_TOKEN;
    bool okay = parse_value(&parser, MCP_JSON_NO_TOKEN, 0U, &root);
    skip_space(&parser);
    if (!okay || parser.cursor != length || root == MCP_JSON_NO_TOKEN) {
        mcp_json_doc_destroy(out);
        return false;
    }
    out->root = root;
    return true;
}

void mcp_json_doc_destroy(mcp_json_doc *doc)
{
    if (doc == NULL) return;
    free(doc->tokens);
    *doc = (mcp_json_doc){0};
}

size_t mcp_json_object_get(const mcp_json_doc *doc, size_t object, const char *key)
{
    if (doc == NULL || key == NULL || object >= doc->token_count ||
        doc->tokens[object].type != MCP_JSON_OBJECT) return MCP_JSON_NO_TOKEN;
    size_t token = doc->tokens[object].first_child;
    while (token != MCP_JSON_NO_TOKEN) {
        size_t value = doc->tokens[token].next_sibling;
        if (value == MCP_JSON_NO_TOKEN) return MCP_JSON_NO_TOKEN;
        if (mcp_json_string_equals(doc, token, key)) return value;
        token = doc->tokens[value].next_sibling;
    }
    return MCP_JSON_NO_TOKEN;
}

size_t mcp_json_array_get(const mcp_json_doc *doc, size_t array, size_t index)
{
    if (doc == NULL || array >= doc->token_count || doc->tokens[array].type != MCP_JSON_ARRAY)
        return MCP_JSON_NO_TOKEN;
    size_t token = doc->tokens[array].first_child;
    while (token != MCP_JSON_NO_TOKEN && index > 0U) {
        token = doc->tokens[token].next_sibling;
        index--;
    }
    return token;
}

static bool copy_codepoint(uint32_t codepoint, char *out, size_t capacity, size_t *cursor)
{
    uint8_t encoded[4];
    size_t count;
    if (codepoint <= 0x7fU) { encoded[0] = (uint8_t)codepoint; count = 1U; }
    else if (codepoint <= 0x7ffU) {
        encoded[0] = (uint8_t)(0xc0U | (codepoint >> 6U));
        encoded[1] = (uint8_t)(0x80U | (codepoint & 0x3fU)); count = 2U;
    } else if (codepoint <= 0xffffU) {
        encoded[0] = (uint8_t)(0xe0U | (codepoint >> 12U));
        encoded[1] = (uint8_t)(0x80U | ((codepoint >> 6U) & 0x3fU));

